export interface DeliveryPoint { title: string; body: string; }
type Triple<T> = readonly [T, T, T];
type Five<T> = readonly [T, T, T, T, T];
type Cue = readonly [value: string, firstLine: string, secondLine: string];

export interface SimpleDeliveryContent {
  title: readonly [string, string];
  intro: string;
  features: Triple<DeliveryPoint>;
  hub: readonly [string, string];
  hubBody: string;
  nodes: Five<DeliveryPoint>;
  cta: string;
  cues: Triple<Cue>;
}

export interface DeliveryComparisonContent {
  title: readonly [string, string, string];
  intro: string;
  columnTitles: Triple<string>;
  rows: readonly [Triple<string>, Triple<string>, Triple<string>, Triple<string>];
}

const p = (title: string, body: string): DeliveryPoint => ({ title, body });

const comparison = (title: DeliveryComparisonContent["title"], intro: string, columnTitles: Triple<string>, rows: DeliveryComparisonContent["rows"]): DeliveryComparisonContent => ({ title, intro, columnTitles, rows });

