function normalizeRoute(path?: string | null): string {
  const clean = (path || "/").split(/[?#]/, 1)[0].trim().toLowerCase();
  return clean === "/" || clean === "" ? "/" : `/${clean.replace(/^\/+|\/+$/g, "")}/`;
}

export function getSimpleDeliveryContent(path?: string | null): SimpleDeliveryContent {
  return simpleDeliveryContent[normalizeRoute(path)] || fallbackSimple;
}

export function getDeliveryComparisonContent(path?: string | null): DeliveryComparisonContent {
  return deliveryComparisonContent[normalizeRoute(path)] || fallbackComparison;
}
